package org.independent.streambox;

import android.app.*;
import android.os.*;
import android.content.*;
import android.net.Uri;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;

public class MainActivity extends Activity {
 private static final int PICK_M3U=41;
 private final ArrayList<MediaEntry> entries=new ArrayList<>();
 private final Set<String> favorites=new HashSet<>();
 private LinearLayout root, rows; private String filter="all", query="", selectedGroup=null;
 private android.content.SharedPreferences prefs;
 @Override public void onCreate(Bundle state){ super.onCreate(state); prefs=getSharedPreferences("library",0); load(); showHome(); }
 private int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xfff4f4f4);t.setPadding(dp(12),dp(9),dp(12),dp(9));return t;}
 private void base(String title){root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xff10151c);setContentView(root); TextView h=text(title,23);h.setBackgroundColor(0xff182431);root.addView(h); ScrollView sc=new ScrollView(this);rows=new LinearLayout(this);rows.setOrientation(1);sc.addView(rows);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
 private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->action.run());return b;}
 private void showHome(){base("Stream Shelf"); TextView hint=text(entries.isEmpty()?"Import an M3U playlist or connect to your IPTV server.":entries.size()+" items saved on this device",15);rows.addView(hint);
  rows.addView(button("Import M3U file",this::pick)); rows.addView(button("Connect Xtream server",this::xtreamForm));
  rows.addView(button("All channels",()->list("live"))); rows.addView(button("Movies",()->list("movie"))); rows.addView(button("Series",()->list("series"))); rows.addView(button("Favorites",()->list("favorites")));
  rows.addView(button("Settings / clear local library",()->new AlertDialog.Builder(this).setMessage("Playlist and favorites are stored only on this device.").setPositiveButton("Clear library",(d,w)->{entries.clear();favorites.clear();save();showHome();}).setNegativeButton("Close",null).show())); }
 private void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_M3U);}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==PICK_M3U&&result==RESULT_OK&&data!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);InputStream in=getContentResolver().openInputStream(u);List<MediaEntry> parsed=M3uParser.parse(new InputStreamReader(in,"UTF-8"));entries.clear();entries.addAll(parsed);save();new AlertDialog.Builder(this).setMessage("Imported "+parsed.size()+" stream entries.").setPositiveButton("OK",(d,w)->showHome()).show();}catch(Exception e){error("Could not read playlist: "+e.getMessage());}}}
 private void xtreamForm(){base("Connect Xtream server"); EditText server=field("Server URL (https://host:port)");EditText user=field("Username");EditText pass=field("Password");pass.setInputType(129);rows.addView(server);rows.addView(user);rows.addView(pass);rows.addView(button("Load live, movies and series",()->connect(server.getText().toString().trim(),user.getText().toString().trim(),pass.getText().toString())));rows.addView(button("Back",this::showHome));}
 private EditText field(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextColor(-1);e.setHintTextColor(0xffaab3bc);e.setPadding(dp(14),dp(12),dp(14),dp(12));return e;}
 private void connect(String base,String user,String pass){try{URL u=new URL(base);if(!u.getProtocol().equals("https")&&!u.getProtocol().equals("http"))throw new Exception("Use an HTTP or HTTPS server URL.");}catch(Exception e){error("Invalid server URL");return;} TextView status=text("Connecting…",16);rows.addView(status);new Thread(()->{ArrayList<MediaEntry> result=new ArrayList<>();String msg=null;try{
   String api=base.replaceAll("/+$","")+"/player_api.php?username="+enc(user)+"&password="+enc(pass);
   JSONObject auth=new JSONObject(fetch(api)); if(auth.has("user_info")&&!auth.getJSONObject("user_info").optString("auth","1").equals("1"))throw new IOException("Server rejected these credentials.");
   pull(api,"get_live_streams","live",categories(api,"get_live_categories"),result); pull(api,"get_vod_streams","movie",categories(api,"get_vod_categories"),result); pull(api,"get_series","series",categories(api,"get_series_categories"),result);
  }catch(Exception e){msg=e.getMessage()==null?e.toString():e.getMessage();}final String err=msg;runOnUiThread(()->{if(err!=null){error("Connection failed: "+err);return;}entries.clear();entries.addAll(result);save();new AlertDialog.Builder(this).setMessage("Loaded "+result.size()+" items from the server.").setPositiveButton("OK",(d,w)->showHome()).show();});}).start();}
 private String enc(String s)throws Exception{return java.net.URLEncoder.encode(s,"UTF-8");}
 private String fetch(String address)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestProperty("Accept","application/json");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);return out.toString("UTF-8");}finally{c.disconnect();}}
 private Map<String,String> categories(String api,String action)throws Exception{HashMap<String,String> names=new HashMap<>();JSONArray a=new JSONArray(fetch(api+"&action="+action));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);names.put(o.optString("category_id"),o.optString("category_name","Uncategorized"));}return names;}
 private void pull(String api,String action,String type,Map<String,String> cats,List<MediaEntry> out)throws Exception{String json=fetch(api+"&action="+action);JSONArray a=new JSONArray(json);for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String id=o.optString("stream_id",o.optString("series_id"));String ext=o.optString("container_extension",type.equals("live")?"ts":"mp4");String segment=type.equals("live")?"live":type.equals("movie")?"movie":"series";String url=api.substring(0,api.indexOf("/player_api.php"))+"/"+segment+"/"+enc(userFrom(api))+"/"+enc(passFrom(api))+"/"+enc(id)+"."+ext;String cat=o.optString("category_id");out.add(new MediaEntry(o.optString("name","Untitled"),url,cats.containsKey(cat)?cats.get(cat):"Uncategorized",type,o.optString("stream_icon",o.optString("cover"))));}}
 private String userFrom(String s)throws Exception{return Uri.parse("?"+s.substring(s.indexOf('?')+1)).getQueryParameter("username");} private String passFrom(String s)throws Exception{return Uri.parse("?"+s.substring(s.indexOf('?')+1)).getQueryParameter("password");}
 private void list(String type){filter=type;selectedGroup=null;if(type.equals("favorites"))showList();else showCategories();}
 private void showCategories(){base(filter.equals("live")?"Live TV · Categories":filter.equals("movie")?"Movies · Categories":"Series · Categories");rows.addView(button("All items",()->{selectedGroup=null;showList();}));rows.addView(button("Home",this::showHome));TreeSet<String> groups=new TreeSet<>(String.CASE_INSENSITIVE_ORDER);for(MediaEntry e:entries)if(e.type.equals(filter))groups.add(e.group);if(groups.isEmpty())rows.addView(text("No categories or items available.",15));for(final String group:groups)rows.addView(button(group,()->{selectedGroup=group;showList();}));}
 private void showList(){base(filter.equals("live")?"Live TV":filter.equals("movie")?"Movies":filter.equals("series")?"Series":"Favorites");EditText search=field("Search");rows.addView(search);search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString().toLowerCase(Locale.ROOT);render();}public void afterTextChanged(android.text.Editable e){}});rows.addView(button(filter.equals("favorites")?"Home":"Categories",filter.equals("favorites")?this::showHome:this::showCategories));render();}
 private void render(){while(rows.getChildCount()>2)rows.removeViewAt(2);int count=0;for(MediaEntry e:new ArrayList<>(entries)){if(!filter.equals("favorites")&&!e.type.equals(filter))continue;if(filter.equals("favorites")&&!favorites.contains(e.url))continue;if(selectedGroup!=null&&!selectedGroup.equals(e.group))continue;if(!query.isEmpty()&&!e.name.toLowerCase(Locale.ROOT).contains(query)&&!e.group.toLowerCase(Locale.ROOT).contains(query))continue;LinearLayout line=new LinearLayout(this);line.setOrientation(0);TextView name=text(e.name+"\n"+e.group,16);name.setOnClickListener(v->play(e));line.addView(name,new LinearLayout.LayoutParams(0,-2,1));Button fav=new Button(this);fav.setText(favorites.contains(e.url)?"★":"☆");fav.setOnClickListener(v->{if(!favorites.add(e.url))favorites.remove(e.url);save();render();});line.addView(fav);rows.addView(line);View sep=new View(this);sep.setBackgroundColor(0xff293541);rows.addView(sep,new LinearLayout.LayoutParams(-1,dp(1)));count++;}if(count==0)rows.addView(text(entries.isEmpty()?"No streams yet. Import a playlist or connect a server.":"No matching items.",15));}
 private void play(MediaEntry e){if(e.type.equals("series")){openSeries(e);return;}Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.parse(e.url),"video/*");try{startActivity(i);}catch(Exception ex){error("No compatible media player was found. "+ex.getMessage());}}
 private void openSeries(final MediaEntry series){new Thread(new Runnable(){public void run(){try{Uri u=Uri.parse(series.url);List<String> p=u.getPathSegments();if(p.size()<4)throw new IOException("Invalid series URL");String id=p.get(p.size()-1);int dot=id.lastIndexOf('.');if(dot>0)id=id.substring(0,dot);String base=series.url.substring(0,series.url.indexOf("/series/"));String api=base+"/player_api.php?username="+enc(Uri.decode(p.get(p.size()-3)))+"&password="+enc(Uri.decode(p.get(p.size()-2)));JSONObject data=new JSONObject(fetch(api+"&action=get_series_info&series_id="+enc(Uri.decode(id))));JSONObject seasons=data.optJSONObject("episodes");final ArrayList<MediaEntry> eps=new ArrayList<>();if(seasons!=null){Iterator<String> keys=seasons.keys();while(keys.hasNext()){JSONArray arr=seasons.optJSONArray(keys.next());if(arr==null)continue;for(int j=0;j<arr.length();j++){JSONObject ep=arr.getJSONObject(j);String eid=ep.optString("id");String ext=ep.optString("container_extension","mp4");eps.add(new MediaEntry("S"+ep.optString("season","?")+" E"+ep.optString("episode_num","?")+" · "+ep.optString("title","Episode"),base+"/series/"+p.get(p.size()-3)+"/"+p.get(p.size()-2)+"/"+enc(eid)+"."+ext,series.group,"episode",ep.optString("info")));}}}runOnUiThread(new Runnable(){public void run(){if(eps.isEmpty()){error("This series has no episode list from the server.");return;}String[] labels=new String[eps.size()];for(int i=0;i<eps.size();i++)labels[i]=eps.get(i).name;new AlertDialog.Builder(MainActivity.this).setTitle(series.name).setItems(labels,(d,which)->play(eps.get(which))).setNegativeButton("Close",null).show();}});}catch(Exception ex){runOnUiThread(new Runnable(){public void run(){error("Could not load series episodes: "+ex.getMessage());}});}}}).start();}
 private void error(String msg){new AlertDialog.Builder(this).setTitle("Stream Shelf").setMessage(msg).setPositiveButton("OK",null).show();}
 private void save(){JSONArray a=new JSONArray();for(MediaEntry e:entries){JSONObject o=new JSONObject();try{o.put("n",e.name);o.put("u",e.url);o.put("g",e.group);o.put("t",e.type);o.put("l",e.logo);}catch(Exception ignored){}a.put(o);}prefs.edit().putString("items",a.toString()).putStringSet("favorites",new HashSet<>(favorites)).apply();}
 private void load(){favorites.addAll(prefs.getStringSet("favorites",Collections.emptySet()));try{JSONArray a=new JSONArray(prefs.getString("items","[]"));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);entries.add(new MediaEntry(o.optString("n"),o.optString("u"),o.optString("g"),o.optString("t"),o.optString("l")));}}catch(Exception ignored){}}
}
